import type { BuildOptions, Page } from './types';

/**
 * Shared, mutable state threaded through a single build. Plugins read and
 * write to this context through their lifecycle hooks.
 */
export interface PluginContext {
  options: BuildOptions;
  pages: Page[];
  outputDir: string;
}

/**
 * The lifecycle contract every SSG plugin implements. All hooks are optional
 * and synchronous; the engine invokes them in plugin order for each phase.
 */
export interface Plugin {
  name: string;

  /** Runs once at the very start of a build, before any work is done. */
  onStart?(context: PluginContext): void;

  /** Runs after pages are read and before any file is rendered or written. */
  beforeBuild?(context: PluginContext): void;

  /** Runs once after all output files have been written. */
  afterBuild?(context: PluginContext): void;

  /** Runs once per page, in order, before the page is written to disk. */
  onFile?(page: Page, context: PluginContext): void;

  /** Runs once at the very end of a build. */
  onEnd?(context: PluginContext): void;
}

export type PluginHook = Exclude<keyof Plugin, 'name'>;

/**
 * Invoke a single phase hook across every plugin, in order.
 */
export function runHook(plugins: Plugin[], hook: PluginHook, context: PluginContext): void {
  for (const plugin of plugins) {
    if (hook === 'onFile') continue;
    const handler = plugin[hook];
    if (handler) handler.call(plugin, context);
  }
}

/**
 * Invoke the per-page `onFile` hook across every plugin, in order.
 */
export function runFileHooks(plugins: Plugin[], page: Page, context: PluginContext): void {
  for (const plugin of plugins) {
    if (plugin.onFile) plugin.onFile(page, context);
  }
}

import type { BuildOptions, Page } from './types';

/**
 * Shared, mutable state threaded through a single build. Plugins read and
 * write to this context through their lifecycle hooks.
 */
export interface PluginContext {
  options: BuildOptions;
  pages: Page[];
  outputDir: string;
}

/**
 * The lifecycle contract every SSG plugin implements. All hooks are optional
 * and synchronous; the engine invokes them in plugin order for each phase.
 */
export interface Plugin {
  name: string;

  /** Runs once at the very start of a build, before any work is done. */
  onStart?(context: PluginContext): void;

  /** Runs after pages are read and before any file is rendered or written. */
  beforeBuild?(context: PluginContext): void;

  /** Runs once after all output files have been written. */
  afterBuild?(context: PluginContext): void;

  /** Runs once per page, in order, before the page is written to disk. */
  onFile?(page: Page, context: PluginContext): void;

  /** Runs once at the very end of a build. */
  onEnd?(context: PluginContext): void;
}

export type PluginLifecycleHook = 'onStart' | 'beforeBuild' | 'afterBuild' | 'onEnd';

/**
 * Invoke a single phase hook across every plugin, in order.
 */
export function runHook(plugins: Plugin[], hook: PluginLifecycleHook, context: PluginContext): void {
  for (const plugin of plugins) {
    const handler = plugin[hook];
    if (handler) handler.call(plugin, context);
  }
}

/**
 * Invoke the per-page `onFile` hook across every plugin, in order.
 */
export function runFileHooks(plugins: Plugin[], page: Page, context: PluginContext): void {
  for (const plugin of plugins) {
    if (plugin.onFile) plugin.onFile(page, context);
  }
}

import fs from 'fs';
import path from 'path';
import { marked } from 'marked';
import { parseMarkdown } from '../frontmatter';
import type { Plugin, PluginContext } from '../plugin';
import type { Page } from '../types';

const MARKDOWN_EXTENSIONS = ['.md', '.markdown'];

/**
 * Built-in plugin that reads Markdown files from the content directory,
 * extracts frontmatter, and renders the body to HTML.
 */
export class MarkdownPlugin implements Plugin {
  name = 'markdown';

  beforeBuild(context: PluginContext): void {
    context.pages = readPages(context.options.contentDir);
  }
}

function readPages(contentDir: string): Page[] {
  if (!fs.existsSync(contentDir)) {
    throw new Error(`Content directory not found: ${contentDir}`);
  }

  const entries = fs.readdirSync(contentDir);
  const pages: Page[] = [];

  for (const entry of entries.sort()) {
    const ext = path.extname(entry);
    if (!MARKDOWN_EXTENSIONS.includes(ext)) continue;

    const filePath = path.join(contentDir, entry);
    const raw = fs.readFileSync(filePath, 'utf-8');
    const { data, content } = parseMarkdown(raw);
    const slug = slugify(entry);

    pages.push({
      slug,
      title: typeof data.title === 'string' && data.title.trim() !== '' ? data.title : slug,
      date: normalizeDate(data.date),
      tags: normalizeTags(data.tags),
      html: marked.parse(content) as string,
      sourcePath: filePath,
      template: typeof data.template === 'string' && data.template.trim() !== '' ? data.template.trim() : undefined,
      layout: typeof data.layout === 'string' && data.layout.trim() !== '' ? data.layout.trim() : undefined,
      data,
    });
  }

  return pages;
}

function slugify(filename: string): string {
  return path.basename(filename, path.extname(filename));
}

function normalizeDate(date: unknown): string | undefined {
  if (typeof date === 'string') return date;
  if (date instanceof Date && !Number.isNaN(date.getTime())) {
    return date.toISOString().slice(0, 10);
  }
  return undefined;
}

function normalizeTags(tags: unknown): string[] {
  if (Array.isArray(tags)) {
    return tags.map((tag) => String(tag).trim()).filter(Boolean);
  }
  if (typeof tags === 'string') {
    return tags
      .split(',')
      .map((tag) => tag.trim())
      .filter(Boolean);
  }
  return [];
}

import fs from 'fs';
import path from 'path';
import { TemplateEngine, TemplateContext } from '../templates';
import type { Plugin, PluginContext } from '../plugin';
import type { Page } from '../types';

const DEFAULT_TEMPLATES_DIR = './templates';

/**
 * Built-in plugin that renders pages through Handlebars templates and layouts
 * when a templates directory exists, otherwise falls back to the built-in
 * HTML renderer. It also writes the site index.
 */
export class TemplatePlugin implements Plugin {
  name = 'template';

  private templatesDir = DEFAULT_TEMPLATES_DIR;
  private engine: TemplateEngine | undefined;
  private useTemplates = false;

  beforeBuild(context: PluginContext): void {
    this.templatesDir = context.options.templatesDir ?? DEFAULT_TEMPLATES_DIR;
    this.engine = new TemplateEngine({ templatesDir: this.templatesDir });
    this.useTemplates = this.engine.hasTemplatesDir();
  }

  onFile(page: Page): void {
    const engine = this.engine!;
    page.html = this.useTemplates ? renderPageWithTemplate(page, engine) : renderPage(page);
  }

  afterBuild(context: PluginContext): void {
    const indexHtml = renderIndex(context.pages);
    fs.writeFileSync(path.join(context.outputDir, 'index.html'), indexHtml);
  }
}

function renderPageWithTemplate(page: Page, engine: TemplateEngine): string {
  const context: TemplateContext = {
    ...page.data,
    title: page.title,
    date: page.date,
    tags: page.tags,
    slug: page.slug,
    body: page.html,
    content: page.html,
  };

  return engine.render(page.template, page.layout, context);
}

function renderPage(page: Page): string {
  const tagsMarkup = page.tags.length
    ? `<ul class="tags">${page.tags.map((tag) => `<li>${escapeHtml(tag)}</li>`).join('')}</ul>`
    : '';
  const dateMarkup = page.date ? `<p class="date">${escapeHtml(page.date)}</p>` : '';

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(page.title)}</title>
</head>
<body>
  <header>
    <h1>${escapeHtml(page.title)}</h1>
${dateMarkup}
${tagsMarkup}
  </header>
  <nav><a href="index.html">&larr; All posts</a></nav>
  <article>
${page.html}
  </article>
</body>
</html>
`;
}

function renderIndex(pages: Page[]): string {
  const sorted = [...pages].sort(byDateDesc);
  const items = sorted
    .map((page) => {
      const meta = [page.date, page.tags.length ? page.tags.join(', ') : '']
        .filter(Boolean)
        .join(' \u2014 ');
      const metaMarkup = meta ? ` <span class="meta">${escapeHtml(meta)}</span>` : '';
      return `    <li><a href="${escapeHtml(page.slug)}.html">${escapeHtml(page.title)}</a>${metaMarkup}</li>`;
    })
    .join('\n');

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>All Posts</title>
</head>
<body>
  <header>
    <h1>All Posts</h1>
  </header>
  <ul>
${items}
  </ul>
</body>
</html>
`;
}

function byDateDesc(a: Page, b: Page): number {
  if (!a.date && !b.date) return a.title.localeCompare(b.title);
  if (!a.date) return 1;
  if (!b.date) return -1;
  return b.date.localeCompare(a.date);
}

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

import fs from 'fs';
import http from 'http';
import net from 'net';
import path from 'path';
import { WebSocketServer, WebSocket } from 'ws';
import { watch, FSWatcher } from 'chokidar';
import { build } from '../engine';
import type { Plugin } from '../plugin';
import type { ServeOptions } from '../types';

export const LIVE_RELOAD_PATH = '/__ssg_livereload';

const RELOAD_MESSAGE = 'reload';
const DEFAULT_HOST = 'localhost';
const DEFAULT_PORT = 3000;
const REBUILD_DEBOUNCE_MS = 100;

const HTML_EXTENSIONS = ['.html', '.htm'];

const LIVE_RELOAD_SCRIPT = `<script>(function(){try{var s=new WebSocket((location.protocol==='https:'?'wss://':'ws://')+location.host+'${LIVE_RELOAD_PATH}');s.onmessage=function(){location.reload();};}catch(e){}})();</script>`;

/**
 * Inject the live-reload WebSocket client script into an HTML document.
 * The script is inserted just before the closing `</body>` tag when present,
 * otherwise appended to the end of the document.
 */
export function injectLiveReloadScript(html: string): string {
  const closeBody = html.lastIndexOf('</body>');
  if (closeBody !== -1) {
    return html.slice(0, closeBody) + LIVE_RELOAD_SCRIPT + html.slice(closeBody);
  }
  return html + LIVE_RELOAD_SCRIPT;
}

export interface DevServerHandle {
  url: string;
  port: number;
  rebuild(): void;
  close(): Promise<void>;
}

/**
 * Built-in plugin that provides the live-reload development server. It serves
 * a freshly built site from the output directory, watches the content and
 * template directories with chokidar, rebuilds on change, and pushes a reload
 * message to connected browsers over a WebSocket.
 */
export class DevServerPlugin implements Plugin {
  name = 'dev-server';

  start(options: ServeOptions): Promise<DevServerHandle> {
    return startDevServer(options);
  }
}

/**
 * A live-reload development server that serves a freshly built site from the
 * output directory, watches the content and template directories with
 * chokidar, rebuilds on change, and pushes a reload message to connected
 * browsers over a WebSocket.
 */
export function startDevServer(options: ServeOptions): Promise<DevServerHandle> {
  return new Promise((resolve, reject) => {
    const port = options.port ?? DEFAULT_PORT;
    const host = options.host ?? DEFAULT_HOST;
    const outputDir = path.resolve(options.outputDir);

    let closed = false;
    let rebuildTimer: NodeJS.Timeout | null = null;
    let watcher: FSWatcher | null = null;
    let wss: WebSocketServer | null = null;
    const sockets = new Set<net.Socket>();

    const server = http.createServer((req, res) => {
      const urlPath = (req.url ?? '/').split('?')[0];

      if (urlPath === LIVE_RELOAD_PATH) {
        res.writeHead(404);
        res.end();
        return;
      }

      let relative: string;
      try {
        relative = decodeURIComponent(urlPath === '/' ? '/index.html' : urlPath);
      } catch {
        res.writeHead(400);
        res.end('Bad Request');
        return;
      }
      const filePath = path.resolve(outputDir, `.${relative}`);

      if (!filePath.startsWith(outputDir + path.sep) && filePath !== outputDir) {
        res.writeHead(403);
        res.end('Forbidden');
        return;
      }

      let content: Buffer;
      try {
        content = fs.readFileSync(filePath);
      } catch {
        res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
        res.end('Not Found');
        return;
      }

      const ext = path.extname(filePath).toLowerCase();
      const isHtml = HTML_EXTENSIONS.includes(ext);
      const headers: Record<string, string> = isHtml
        ? { 'Content-Type': 'text/html; charset=utf-8' }
        : {};

      let body: Buffer = content;
      if (isHtml) {
        body = Buffer.from(injectLiveReloadScript(content.toString('utf-8')), 'utf-8');
      }
      res.writeHead(200, headers);
      res.end(body);
    });

    server.on('connection', (socket) => {
      sockets.add(socket);
      socket.on('close', () => sockets.delete(socket));
    });

    const broadcast = () => {
      if (!wss) return;
      for (const client of wss.clients) {
        if (client.readyState === WebSocket.OPEN) {
          client.send(RELOAD_MESSAGE);
        }
      }
    };

    const rebuild = () => {
      try {
        build({
          contentDir: options.contentDir,
          outputDir: options.outputDir,
          templatesDir: options.templatesDir,
        });
        console.log(`[ssg] rebuilt site in ${options.outputDir}`);
      } catch (err) {
        console.error(`[ssg] build failed: ${(err as Error).message}`);
        return;
      }
      broadcast();
    };

    const scheduleRebuild = () => {
      if (closed) return;
      if (rebuildTimer) clearTimeout(rebuildTimer);
      rebuildTimer = setTimeout(() => {
        rebuildTimer = null;
        rebuild();
      }, REBUILD_DEBOUNCE_MS);
    };

    server.once('error', (err) => {
      reject(err);
    });

    server.listen(port, host, () => {
      try {
        wss = new WebSocketServer({ server, path: LIVE_RELOAD_PATH });
      } catch (err) {
        server.close();
        reject(err as Error);
        return;
      }

      const watchedPaths: string[] = [path.resolve(options.contentDir)];
      if (options.templatesDir) {
        watchedPaths.push(path.resolve(options.templatesDir));
      }

      try {
        rebuild();
      } catch {
        // The initial build may fail if the content directory does not exist
        // yet; keep serving and let chokidar trigger a rebuild once it appears.
      }

      watcher = watch(watchedPaths, {
        ignoreInitial: true,
      });

      watcher.on('all', () => {
        scheduleRebuild();
      });

      watcher.on('error', (err) => {
        console.error(`[ssg] watcher error: ${(err as Error).message ?? String(err)}`);
      });

      const address = server.address();
      const boundPort = typeof address === 'object' && address !== null ? address.port : port;

      const handle: DevServerHandle = {
        url: `http://${host}:${boundPort}`,
        port: boundPort,
        rebuild,
        close: async () => {
          if (closed) return;
          closed = true;
          if (rebuildTimer) clearTimeout(rebuildTimer);
          if (watcher) await watcher.close();
          // Let the watcher's underlying fs.watch handles settle before tearing
          // down the HTTP server; inotify cleanup is not fully synchronous.
          await new Promise<void>((done) => setImmediate(done));
          if (wss) {
            for (const client of wss.clients) client.terminate();
            wss.close();
          }
          await new Promise<void>((done) => {
            server.close(() => done());
            server.closeAllConnections();
            for (const socket of sockets) socket.destroy();
          });
        },
      };

      // Wait for the watcher's initial scan to finish before handing the server
      // back, so the watcher is fully initialized (and closable) immediately.
      const readyWatcher = watcher;
      const waitForReady = new Promise<void>((readyResolve) => {
        const readyTimer = setTimeout(readyResolve, 1000);
        readyWatcher.once('ready', () => {
          clearTimeout(readyTimer);
          readyResolve();
        });
      });

      waitForReady.then(() => resolve(handle));
    });
  });
}

import fs from 'fs';
import path from 'path';
import type { Plugin } from './plugin';
import type { BuildOptions } from './types';
import { MarkdownPlugin } from './plugins/markdown';
import { TemplatePlugin } from './plugins/template';
import { DevServerPlugin } from './plugins/dev-server';

export interface SsgConfig {
  plugins?: Plugin[];
}

const CONFIG_FILENAMES = ['ssg.config.ts', 'ssg.config.js', 'ssg.config.json'];

/**
 * The set of built-in plugins that ship with the SSG. They are always loaded
 * first so that core behavior (Markdown parsing, template rendering, and the
 * dev server) is available regardless of the user's config.
 */
export function createBuiltInPlugins(): Plugin[] {
  return [new MarkdownPlugin(), new TemplatePlugin(), new DevServerPlugin()];
}

/**
 * Resolve the plugins to use for a build: the built-in plugins followed by any
 * plugins supplied directly on the options or declared in `ssg.config.ts`.
 */
export function loadPlugins(options: BuildOptions): Plugin[] {
  const plugins = createBuiltInPlugins();

  if (options.plugins && options.plugins.length > 0) {
    plugins.push(...options.plugins);
    return plugins;
  }

  const configPath = options.config ?? findConfigPath();
  if (!configPath) return plugins;

  const config = loadConfigFile(configPath);
  if (config && config.plugins) {
    plugins.push(...config.plugins);
  }

  return plugins;
}

function findConfigPath(): string | undefined {
  const cwd = process.cwd();
  for (const filename of CONFIG_FILENAMES) {
    const candidate = path.join(cwd, filename);
    if (fs.existsSync(candidate)) return candidate;
  }
  return undefined;
}

function loadConfigFile(configPath: string): SsgConfig {
  const ext = path.extname(configPath).toLowerCase();

  if (ext === '.json') {
    return JSON.parse(fs.readFileSync(configPath, 'utf-8')) as SsgConfig;
  }

  if (ext === '.js') {
    return normalizeConfig(require(configPath));
  }

  return loadTypeScriptConfig(configPath);
}

function loadTypeScriptConfig(configPath: string): SsgConfig {
  const source = fs.readFileSync(configPath, 'utf-8');
  // eslint-disable-next-line @typescript-eslint/no-var-requires
  const ts = require('typescript') as typeof import('typescript');
  const transpiled = ts.transpileModule(source, {
    compilerOptions: {
      module: ts.ModuleKind.CommonJS,
      target: ts.ScriptTarget.ES2020,
      esModuleInterop: true,
    },
  }).outputText;

  // eslint-disable-next-line @typescript-eslint/no-var-requires
  const Module = require('module') as typeof import('module');
  const mod = new Module(configPath, module);
  mod.filename = configPath;
  mod.paths = (Module as unknown as { _nodeModulePaths(dir: string): string[] })._nodeModulePaths(
    path.dirname(configPath)
  );
  mod._compile(transpiled, configPath);

  const exported = (mod.exports as { default?: SsgConfig } | SsgConfig);
  return normalizeConfig(
    typeof exported === 'object' && exported !== null && 'default' in exported
      ? (exported as { default?: SsgConfig }).default ?? {}
      : exported
  );
}

function normalizeConfig(config: unknown): SsgConfig {
  if (config && typeof config === 'object' && 'plugins' in config) {
    return config as SsgConfig;
  }
  return {};
}

import fs from 'fs';
import path from 'path';
import { runFileHooks, runHook, Plugin, PluginContext } from './plugin';
import { loadPlugins } from './config';
import type { BuildOptions, BuildResult, Page } from './types';

/**
 * The core SSG engine. It loads plugins, then orchestrates the plugin pipeline:
 *
 *   onStart -> beforeBuild -> onFile (per page) -> afterBuild -> onEnd
 *
 * The built-in MarkdownPlugin populates the page list during `beforeBuild` and
 * the built-in TemplatePlugin renders each page during `onFile`, so the engine
 * itself only concerns itself with wiring hooks together and writing files.
 */
export function build(options: BuildOptions): BuildResult {
  const plugins: Plugin[] = loadPlugins(options);
  const context: PluginContext = {
    options,
    pages: [],
    outputDir: options.outputDir,
  };

  runHook(plugins, 'onStart', context);
  runHook(plugins, 'beforeBuild', context);

  fs.mkdirSync(context.outputDir, { recursive: true });

  // Snapshot the parsed pages before per-page hooks mutate them, so the return
  // value mirrors the raw (Markdown) pages rather than the rendered output.
  const resultPages: Page[] = context.pages.map((page) => ({ ...page }));

  for (const page of context.pages) {
    runFileHooks(plugins, page, context);
  }

  for (const page of context.pages) {
    fs.writeFileSync(path.join(context.outputDir, `${page.slug}.html`), page.html);
  }

  runHook(plugins, 'afterBuild', context);
  runHook(plugins, 'onEnd', context);

  return { pages: resultPages, outputDir: context.outputDir };
}

export {
  startDevServer,
