import fs from 'fs';
import path from 'path';
import type { Plugin } from './plugin';
import type { BuildOptions } from './types';
import { MarkdownPlugin } from './plugins/markdown';
import { TemplatePlugin } from './plugins/template';
import { DevServerPlugin } from './plugins/dev-server';

export interface SsgConfig {
  plugins?: Plugin[];
}

const CONFIG_FILENAMES = ['ssg.config.ts', 'ssg.config.js', 'ssg.config.json'];

/**
 * The set of built-in plugins that ship with the SSG. They are always loaded
 * first so that core behavior (Markdown parsing, template rendering, and the
 * dev server) is available regardless of the user's config.
 */
export function createBuiltInPlugins(): Plugin[] {
  return [new MarkdownPlugin(), new TemplatePlugin(), new DevServerPlugin()];
}

/**
 * Resolve the plugins to use for a build: the built-in plugins followed by any
 * plugins supplied directly on the options or declared in `ssg.config.ts`.
 */
export function loadPlugins(options: BuildOptions): Plugin[] {
  const plugins = createBuiltInPlugins();

  if (options.plugins && options.plugins.length > 0) {
    plugins.push(...options.plugins);
    return plugins;
  }

  const configPath = options.config ?? findConfigPath();
  if (!configPath) return plugins;

  const config = loadConfigFile(configPath);
  if (config && config.plugins) {
    plugins.push(...config.plugins);
  }

  return plugins;
}

function findConfigPath(): string | undefined {
  const cwd = process.cwd();
  for (const filename of CONFIG_FILENAMES) {
    const candidate = path.join(cwd, filename);
    if (fs.existsSync(candidate)) return candidate;
  }
  return undefined;
}

function loadConfigFile(configPath: string): SsgConfig {
  const ext = path.extname(configPath).toLowerCase();

  if (ext === '.json') {
    return normalizeConfig(JSON.parse(fs.readFileSync(configPath, 'utf-8')));
  }

  if (ext === '.js') {
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    return normalizeConfig(require(configPath));
  }

  return loadTypeScriptConfig(configPath);
}

function loadTypeScriptConfig(configPath: string): SsgConfig {
  const source = fs.readFileSync(configPath, 'utf-8');
  // eslint-disable-next-line @typescript-eslint/no-var-requires
  const ts = require('typescript') as typeof import('typescript');
  const transpiled = ts.transpileModule(source, {
    compilerOptions: {
      module: ts.ModuleKind.CommonJS,
      target: ts.ScriptTarget.ES2020,
      esModuleInterop: true,
    },
  }).outputText;

  // eslint-disable-next-line @typescript-eslint/no-var-requires
  const Module: any = require('module');
  const mod = new Module(configPath, module);
  mod.filename = configPath;
  mod.paths = Module._nodeModulePaths(path.dirname(configPath));
  mod._compile(transpiled, configPath);

  const exported = mod.exports;
  if (exported && typeof exported === 'object' && 'default' in exported) {
    return normalizeConfig(exported.default);
  }
  return normalizeConfig(exported);
}

function normalizeConfig(config: unknown): SsgConfig {
  if (config && typeof config === 'object' && 'plugins' in config) {
    return config as SsgConfig;
  }
  return {};
}

import fs from 'fs';
import os from 'os';
import path from 'path';
import { build } from '../src/ssg';
import { createBuiltInPlugins, loadPlugins } from '../src/config';
import { MarkdownPlugin } from '../src/plugins/markdown';
import { TemplatePlugin } from '../src/plugins/template';
import { DevServerPlugin } from '../src/plugins/dev-server';
import type { Plugin } from '../src/plugin';

function makeTempDir(): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-plugin-'));
}

function writeFile(dir: string, name: string, content: string): string {
  const filePath = path.join(dir, name);
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, content);
  return filePath;
}

describe('plugin system', () => {
  it('loads the built-in plugins in order', () => {
    const plugins = createBuiltInPlugins();
    expect(plugins.map((p) => p.name)).toEqual(['markdown', 'template', 'dev-server']);
    expect(plugins[0]).toBeInstanceOf(MarkdownPlugin);
    expect(plugins[1]).toBeInstanceOf(TemplatePlugin);
    expect(plugins[2]).toBeInstanceOf(DevServerPlugin);
  });

  it('runs the full plugin pipeline in order', () => {
    const contentDir = makeTempDir();
    const outputDir = path.join(makeTempDir(), 'dist');
    writeFile(contentDir, 'a.md', '---\ntitle: A\n---\nBody a');
    writeFile(contentDir, 'b.md', '---\ntitle: B\n---\nBody b');

    const events: string[] = [];
    const recorder: Plugin = {
      name: 'recorder',
      onStart: () => events.push('onStart'),
      beforeBuild: () => events.push('beforeBuild'),
      onFile: (page) => events.push(`onFile:${page.slug}`),
      afterBuild: () => events.push('afterBuild'),
      onEnd: () => events.push('onEnd'),
    };

    build({ contentDir, outputDir, plugins: [recorder] });

    expect(events).toEqual([
      'onStart',
      'beforeBuild',
      'onFile:a',
      'onFile:b',
      'afterBuild',
      'onEnd',
    ]);

    fs.rmSync(contentDir, { recursive: true, force: true });
    fs.rmSync(path.dirname(outputDir), { recursive: true, force: true });
  });

  it('lets a custom plugin transform the rendered output', () => {
    const contentDir = makeTempDir();
    const outputDir = path.join(makeTempDir(), 'dist');
    writeFile(contentDir, 'hello.md', '---\ntitle: Hello\n---\nBody text.');

    const banner: Plugin = {
      name: 'banner',
      onFile: (page) => {
        page.html = `<!-- banner -->\n${page.html}`;
      },
    };

    build({ contentDir, outputDir, plugins: [banner] });

    const html = fs.readFileSync(path.join(outputDir, 'hello.html'), 'utf-8');
    expect(html).toContain('<!-- banner -->');
    expect(html).toContain('<h1>Hello</h1>');

    fs.rmSync(contentDir, { recursive: true, force: true });
    fs.rmSync(path.dirname(outputDir), { recursive: true, force: true });
  });

  it('loads additional plugins from a TypeScript config file', () => {
    const contentDir = makeTempDir();
    const outputDir = path.join(makeTempDir(), 'dist');
    const configPath = path.join(makeTempDir(), 'ssg.config.ts');
    writeFile(contentDir, 'hello.md', '---\ntitle: Hello\n---\nBody.');

    writeFile(
      configPath,
      [
        'export default {',
        '  plugins: [',
        '    {',
        "      name: 'stamp',",
        '      onFile(page: any) {',
        "        page.html = page.html + '\\n<!-- stamped -->';",
        '      },',
        '    },',
        '  ],',
        '};',
        '',
      ].join('\n')
    );

    const plugins = loadPlugins({ contentDir, outputDir, config: configPath });
    expect(plugins.map((p) => p.name)).toEqual(['markdown', 'template', 'dev-server', 'stamp']);

    build({ contentDir, outputDir, config: configPath });

    const html = fs.readFileSync(path.join(outputDir, 'hello.html'), 'utf-8');
    expect(html).toContain('<!-- stamped -->');

    fs.rmSync(contentDir, { recursive: true, force: true });
    fs.rmSync(path.dirname(outputDir), { recursive: true, force: true });
    fs.rmSync(path.dirname(configPath), { recursive: true, force: true });
  });
});
